#The asset's measure tags, browsed once per asset (when its tagPath changes) rather than every refresh
if (value or None) is None: return []
tagSearchList = [
	{'tagPath': value, 'filters': {"tagType": "UdtInstance", "typeId": "Kanoa/measure", "recursive": True}},
	{'tagPath': value, 'filters': {"tagType": "UdtInstance", "typeId": "[Kanoa]_types_/Kanoa/measure", "recursive": True}}
]
measureTags = []
for ts in tagSearchList:
	for result in system.tag.browse(path = ts['tagPath'], filter = ts['filters']).results:
		measureTags.append({'tagName': str(result['name']), 'tagPath': str(result['fullPath'])})
return measureTags

